import React, { useState, useEffect } from 'react';
import { getUsers, deleteUser, updateUser } from '../services/api';

const UserManagement = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingUser, setEditingUser] = useState(null);
  const [updatedRole, setUpdatedRole] = useState('');
  const [actionLoading, setActionLoading] = useState(false); // For loading states on actions

  useEffect(() => {
    const fetchUsers = async () => {
      setLoading(true);
      try {
        const response = await getUsers();
        // Ensure the response is an array
        if (Array.isArray(response)) {
          setUsers(response);
          setError(null);
        } else {
          throw new Error('Invalid user data format.');
        }
      } catch (error) {
        setError('Error fetching users. Please try again later.');
      } finally {
        setLoading(false);
      }
    };
    fetchUsers();
  }, []);

  const handleDelete = async (userId) => {
    const confirmDelete = window.confirm('Are you sure you want to delete this user?');
    if (!confirmDelete) return; // Exit if user cancels deletion

    setActionLoading(true); // Show loading state
    try {
      await deleteUser(userId);
      setUsers((prevUsers) => prevUsers.filter(user => user._id !== userId));
      setError(null);
    } catch (error) {
      setError('Error deleting user. Please try again later.');
    } finally {
      setActionLoading(false); // Hide loading state
    }
  };

  const handleUpdate = async () => {
    if (!editingUser || !editingUser._id) {
      setError('Invalid user data. User ID is missing.');
      return;
    }

    if (!updatedRole) {
      setError('Please select a role before submitting.');
      return;
    }

    setActionLoading(true); // Show loading state
    try {
      const updatedData = { ...editingUser, role: updatedRole };
      const updatedUser = await updateUser(editingUser._id, updatedData);
      setUsers((prevUsers) =>
        prevUsers.map((user) => (user._id === editingUser._id ? updatedUser : user))
      );
      setEditingUser(null);
      setUpdatedRole('');
      setError(null);
    } catch (error) {
      setError('Error updating user. Please try again later.');
      console.error(error); // Log error for debugging
    } finally {
      setActionLoading(false); // Hide loading state
    }
  };

  const openEditForm = (user) => {
    setEditingUser({ ...user });
    setUpdatedRole(user.role);
  };

  const closeEditForm = () => {
    setEditingUser(null);
    setUpdatedRole('');
  };

  return (
    <div>
      
      {loading && <p>Loading users...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}

      {users.length > 0 ? (
        <table>
          <thead>
            <tr>
              <th>Username</th>
              <th>Role</th>
              <th>Franchise</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr key={user._id}>
                <td>{user.username}</td>
                <td>{user.role}</td>
                <td>{user.franchise?.name || 'N/A'}</td>
                <td>
                  <button onClick={() => openEditForm(user)}>Edit</button>
                  <button onClick={() => handleDelete(user._id)} disabled={actionLoading}>
                    {actionLoading ? 'Deleting...' : 'Delete'}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No users found.</p>
      )}

      {editingUser && (
        <div className="edit-form">
          <h2>Edit User</h2>
          <form onSubmit={(e) => { e.preventDefault(); handleUpdate(); }}>
            <div>
              <label htmlFor="username">Username:</label>
              <input
                id="username"
                type="text"
                value={editingUser.username}
                onChange={(e) =>
                  setEditingUser((prevUser) => ({ ...prevUser, username: e.target.value }))
                }
              />
            </div>
            <div>
              <label htmlFor="role">Role:</label>
              <select
                id="role"
                value={updatedRole}
                onChange={(e) => setUpdatedRole(e.target.value)}
              >
                <option value="user">User</option>
                <option value="admin">Admin</option>
              </select>
            </div>
            <div>
              <button type="submit" disabled={actionLoading}>
                {actionLoading ? 'Saving...' : 'Save Changes'}
              </button>
              <button type="button" onClick={closeEditForm}>
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default UserManagement;
